begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table focus_material(source text,manifest jsonb);grant select,insert,update on focus_material to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','996c0000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Material review course','Synthetic source','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','996d0000-0000-4000-8000-000000000001','996c0000-0000-4000-8000-000000000001','Material review unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','996e0000-0000-4000-8000-000000000001','996d0000-0000-4000-8000-000000000001','Material review lesson',1,'Read the school guide.');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','996f0000-0000-4000-8000-000000000001','996e0000-0000-4000-8000-000000000001','Use the guide','practice','Use the guide to apply the procedure.',1);
insert into app.private_assets(school_id,id,owner_id,created_by,name,content_type,byte_size,sha256,state,object_path,purpose,course_id)values('10000000-0000-4000-8000-000000000001','99700000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000004','School guide.txt','text/plain',5,repeat('a',64),'AVAILABLE','synthetic/material-review/guide','COURSE_RESOURCE','996c0000-0000-4000-8000-000000000001');
insert into app.learning_resources(school_id,id,course_id,target_kind,target_id,title,sequence,created_by)values('10000000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001','996c0000-0000-4000-8000-000000000001','activity','996f0000-0000-4000-8000-000000000001','School guide',1,'20000000-0000-4000-8000-000000000004');
insert into app.learning_resource_revisions(school_id,id,resource_id,revision,asset_id,state,reason,created_by)values('10000000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001',1,'99700000-0000-4000-8000-000000000001','PUBLISHED','Synthetic reviewed material','20000000-0000-4000-8000-000000000004');
insert into app.learning_resource_current(school_id,resource_id,revision_id)values('10000000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
insert into focus_material(source)select internal.read_thinking_focus('activity','996f0000-0000-4000-8000-000000000001',null)->>'sourceVersion';
update focus_material set manifest=internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,source);
select is((select manifest->'items'->0->>'title'from focus_material),'School guide','coordinator manifest carries exact authorized human material label');
select is((select manifest->'items'->0->>'revisionId'from focus_material),'99720000-0000-4000-8000-000000000001','manifest binds exact immutable material revision');
select ok((select manifest::text not like '%objectPath%'from focus_material),'manifest does not expose storage paths');
select is(internal.read_thinking_focus_material_delivery('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material),'99710000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001')->'asset'->>'id','99700000-0000-4000-8000-000000000001','private review-purpose delivery resolves only exact manifest asset');
select throws_ok($$select internal.read_thinking_focus_material_delivery('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material),'99710000-0000-4000-8000-000000000001','ffffffff-ffff-4fff-8fff-ffffffffffff')$$,'42501',null,'different material revision cannot be downloaded');
select throws_ok($$select internal.read_learning_resource_delivery('99710000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001')$$,'42501',null,'coordinator general resource delivery remains denied');
select throws_ok($$select internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,'stale-source')$$,'22023',null,'stale material source is denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select throws_ok($$select internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material))$$,'42501',null,'student cannot use review-purpose materials');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material))$$,'42501',null,'parent cannot use review-purpose materials');
reset role;update app.entitlements set enabled=false where school_id='10000000-0000-4000-8000-000000000001'and code='curriculum';set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);select throws_ok($$select internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material))$$,'42501',null,'coordinator current curriculum revocation denies inspection');
reset role;update app.entitlements set enabled=true where school_id='10000000-0000-4000-8000-000000000001'and code='curriculum';set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000132',true);select throws_ok($$select internal.read_thinking_focus_materials('activity','996f0000-0000-4000-8000-000000000001',null,(select source from focus_material))$$,'42501',null,'cross-school review material denied');
reset role;select ok(not has_function_privilege('authenticated','internal.read_thinking_focus_material_delivery(text,uuid,text,text,uuid,uuid)','EXECUTE'),'browser cannot call private review delivery helper');select ok(not has_function_privilege('cuevo_worker','internal.read_thinking_focus_materials(text,uuid,text,text)','EXECUTE'),'worker cannot inspect review material');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.thinking_focus_command('draft','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',0,'expectedSourceVersion',(select source from focus_material),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses','[]'::jsonb),'rationale','Use the supplied school guide.'),'material-preflight-draft',repeat('a',64),'material-test')is not null;
reset role;savepoint unavailable_material_case;update app.private_assets set state='RETIRED'where id='99700000-0000-4000-8000-000000000001';set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source from focus_material),'decision','APPROVE','reason','Attempt approval with unavailable source.','confirmReview',true),'material-retired-approve',repeat('b',64),'material-test')$$,'22023',null,'raw approval cannot bypass unavailable source material');
select lives_ok($$select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source from focus_material),'decision','REJECT','reason','Source material unavailable.','confirmReview',true),'material-retired-reject',repeat('c',64),'material-test')$$,'rejection remains possible with unavailable material');
reset role;
select is((select count(*)from internal.audit_events where entity_type='thinking_focus'and action='thinking_focus.review'and metadata->>'sourceId'='996f0000-0000-4000-8000-000000000001'),1::bigint,'denied approval writes no extra audit');
select is((select count(*)from app.thinking_focus_revisions where source_id='996f0000-0000-4000-8000-000000000001'),2::bigint,'denied approval writes no extra revision');
insert into app.learning_resources(school_id,id,course_id,target_kind,target_id,title,sequence,created_by)select'10000000-0000-4000-8000-000000000001',('99730000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'996c0000-0000-4000-8000-000000000001','activity','996f0000-0000-4000-8000-000000000001','Capacity review guide '||n,n+1,'20000000-0000-4000-8000-000000000004'from generate_series(1,100)n;
insert into app.learning_resource_revisions(school_id,id,resource_id,revision,asset_id,state,reason,created_by)select'10000000-0000-4000-8000-000000000001',('99740000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('99730000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,1,'99700000-0000-4000-8000-000000000001','PUBLISHED','Capacity test source','20000000-0000-4000-8000-000000000004'from generate_series(1,100)n;
insert into app.learning_resource_current(school_id,resource_id,revision_id)select'10000000-0000-4000-8000-000000000001',('99730000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('99740000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,100)n;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update focus_material set source=internal.read_thinking_focus('activity','996f0000-0000-4000-8000-000000000001',null)->>'sourceVersion';
select internal.thinking_focus_command('draft','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',2,'expectedSourceVersion',(select source from focus_material),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','APPLY','additionalProcesses','[]'::jsonb),'rationale','Capacity source needs review.'),'material-capacity-draft',repeat('d',64),'material-test')is not null;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',3,'expectedSourceVersion',(select source from focus_material),'decision','APPROVE','reason','Attempt over-capacity approval.','confirmReview',true),'material-capacity-approve',repeat('e',64),'material-test')$$,'22023',null,'raw approval cannot bypass complete material capacity bound');
reset role;rollback to savepoint unavailable_material_case;release savepoint unavailable_material_case;set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source from focus_material),'decision','APPROVE','reason','Reviewed currently available source.','confirmReview',true),'material-valid-approval',repeat('f',64),'material-test')is not null;
reset role;update app.private_assets set state='RETIRED'where id='99700000-0000-4000-8000-000000000001';set local role cuevo_api;
select lives_ok($$select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source from focus_material),'decision','APPROVE','reason','Reviewed currently available source.','confirmReview',true),'material-valid-approval',repeat('f',64),'material-test')$$,'original approval receipt reconciles after availability changes without a new approval');
select lives_ok($$select internal.thinking_focus_command('review','activity','996f0000-0000-4000-8000-000000000001',null,jsonb_build_object('expectedRevision',2,'expectedSourceVersion',(select source from focus_material),'decision','WITHDRAW','reason','Source is unavailable so withdraw review.','confirmReview',true),'material-unavailable-withdraw',repeat('1',64),'material-test')$$,'withdrawal remains permitted when material is unavailable');
select*from finish();rollback;
